#include <ctype.h>

class text_file
{
  char io[64];
  char the_stash[52];
  int my_stash;
  char *buf;
  int bufpos;
  int bufamt;
  bool use_stash;
  int pushbackdata;

public:
  char peek_char();
  char read_char();

private:
  void eat_whitespace();
  bool at_eof() const
  {
    return use_stash ? (bufpos >= bufamt && *(const bool *)(the_stash + 16))
                     : (bufpos >= bufamt && *(const bool *)(io + 16));
  }
};

void error(const char *, ...);

__asm__(".equ peek_char__9text_file, 0x00338110");
__asm__(".equ read_char__9text_file, 0x00338138");
__asm__(".equ error__FPCce, 0x001DFBD8");

#define ISSPACE isspace

void text_file::eat_whitespace()
{
  while(ISSPACE(peek_char()) && !at_eof())
    read_char();

  // C++ style comments.
  while ( peek_char() == '/' && !at_eof())
  {
    read_char();
    if ( peek_char() == '*' )
    {
      while ( !( read_char() == '*' && peek_char() == '/' ) && !at_eof() ) {}
      read_char();
    }
    else
    if ( peek_char() == '/' )
    {
      while ( peek_char() == '/' && !at_eof())
      {
        // Skip to the end of the line.
        while (peek_char()!='\n' && !at_eof())
          read_char();
      }
    }
    else
    {
      error( "Invalid comment." );
    }

    while(ISSPACE(peek_char()) && !at_eof())
      read_char();
  }
}
